def marcar_vendas_e_criar_deposito(apps, schema_editor):
    """Nas empresas que ja usam o extrato: a "Vendas" que veio semeada ganha a
    marca, e o "Deposito de dinheiro" passa a existir. Empresa sem nenhuma
    categoria fica de fora: ela ganha as duas quando semear."""
    CategoriaDeMovimento = apps.get_model("app", "CategoriaDeMovimento")
